const html = $json.data || "";

// ---------------- TITLE ----------------
const title =
  html.match(/<title[^>]*>(.*?)<\/title>/is)?.[1]?.trim() || "";

// ---------------- DESCRIPTION ----------------
const description =
  html.match(
    /<meta[^>]*name=["']description["'][^>]*content=["']([^"]+)["']/i
  )?.[1]?.trim() || "";

// ---------------- BODY ----------------
let body =
  html.match(/<body[^>]*>([\s\S]*?)<\/body>/i)?.[1] || html;

// Remove unwanted tags
body = body
  .replace(/<script[\s\S]*?<\/script>/gi, "")
  .replace(/<style[\s\S]*?<\/style>/gi, "")
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, "")
  .replace(/<!--[\s\S]*?-->/g, "");

// Strip HTML
body = body
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/&#8217;/g, "'")
  .replace(/&#8220;/g, '"')
  .replace(/&#8221;/g, '"')
  .replace(/\s+/g, " ")
  .trim();

// If body is empty, fall back to title + description
let content = body;

if (content.length < 100) {
  content = `${title}. ${description}`;
}

// Limit for LLM
content = content.substring(0, 4000);

const { data, ...rest } = $json;

return {
  json: {
    ...rest,
    title,
    description,
    content
  }
};

if (!$json.text) {
  throw new Error("No text returned from LLM");
}

let txt = $json.text.trim();

// Remove ```json
txt = txt.replace(/^```json/i, "");

// Remove ```
txt = txt.replace(/^```/, "");
txt = txt.replace(/```$/, "").trim();

// Extract JSON portion
const first = txt.indexOf("{");
const last = txt.lastIndexOf("}");

if (first === -1 || last === -1) {
  throw new Error("No JSON found:\n" + txt);
}

txt = txt.substring(first, last + 1);

let result;

try {
  result = JSON.parse(txt);

} catch (err) {

  // Remove invalid backslashes
  txt = txt.replace(/\\(?!["\\/bfnrtu])/g, "");

  result = JSON.parse(txt);
}

// ----------------------
// Fix missing/null values
// ----------------------

result.industry = result.industry ?? "";
result.summary = result.summary ?? "";
result.ideal_customer = result.ideal_customer ?? "";
result.company_size = result.company_size ?? "";
result.buying_intent = result.buying_intent ?? "";
result.recommended_service = result.recommended_service ?? "";
result.reason = result.reason ?? "";

if (!Array.isArray(result.services)) {
  result.services = [];
}

if (typeof result.score !== "number") {
  result.score = 0;
}

// Remove duplicate services
result.services = [...new Set(result.services)];

// Trim all string values
result.industry = result.industry.trim();
result.summary = result.summary.trim();
result.ideal_customer = result.ideal_customer.trim();
result.company_size = result.company_size.trim();
result.buying_intent = result.buying_intent.trim();
result.recommended_service = result.recommended_service.trim();
result.reason = result.reason.trim();

return {
  json: {
    id: $('Execute a SQL query').item.json.id,
    business_name: $('Execute a SQL query').item.json.business_name,
    website: $('Execute a SQL query').item.json.website,
    instagram: $('Execute a SQL query').item.json.instagram,
    email: $('Execute a SQL query').item.json.email,
    phone: $('Execute a SQL query').item.json.phone,

    ...result
  }
};

let website = ($json.website || "").trim();

if (
  website &&
  !website.startsWith("http://") &&
  !website.startsWith("https://")
) {
  website = "https://" + website;
}

website = website.replace(/\s+/g, "");
website = website.replace(/\/+$/, "");

return {
  json: {
    ...$json,
    website
  }
};

const title = ($json.title || "").trim();
const description = ($json.description || "").trim();
const content = ($json.content || "").trim();

if (!title && !content) {
  return {
    json: {
      ...$json,
      skip: true,
      reason: "Empty website"
    }
  };
}

return {
  json: {
    ...$json,
    title,
    description,
    content,
    skip: false,
    reason: ""
  }
};

